63→// RegisterGate sets a concurrency limit for an agent's tests.
64→// Tests call AcquireSlot/ReleaseSlot to respect this limit.
65→func RegisterGate(name string, max int) {
66→	gates[name] = make(chan struct{}, max)
67→}
