107→// ForEachAgent runs fn as a parallel subtest for every registered agent.
108→// It handles repo setup, concurrency gating, context timeout, and cleanup.
109→// The timeout is scaled by each agent's TimeoutMultiplier.
110→func ForEachAgent(t *testing.T, timeout time.Duration, fn func(t *testing.T, s *RepoState, ctx context.Context)) {
111→	t.Helper()
112→	t.Parallel()
113→	all := agents.All()
114→	if len(all) == 0 {
115→		t.Skip("no agents registered (check E2E_AGENT filter)")
116→	}
117→	for _, agent := range all {
118→		t.Run(agent.Name(), func(t *testing.T) {
119→			s := SetupRepo(t, agent)
120→
121→			// Use the global test deadline for slot wait so we don't
122→			// skip prematurely — only bail if the whole binary is dying.
123→			slotCtx := context.Background()
124→			if deadline, ok := t.Deadline(); ok {
125→				var cancel context.CancelFunc
126→				slotCtx, cancel = context.WithDeadline(slotCtx, deadline)
127→				defer cancel()
128→			}
129→			if err := agents.AcquireSlot(slotCtx, agent); err != nil {
130→				t.Fatalf("timed out waiting for agent slot: %v", err)
131→			}
132→			defer agents.ReleaseSlot(agent)
133→
134→			// Per-test timeout starts after slot is acquired, scaled
135→			// by the agent's multiplier (e.g. 2.5× for gemini).
136→			scaled := time.Duration(float64(timeout) * agent.TimeoutMultiplier())
137→			ctx, cancel := context.WithTimeout(context.Background(), scaled)
138→			defer cancel()
139→			fn(t, s, ctx)
140→		})
141→	}
142→}
