144→// RunPrompt runs an agent prompt, logs the command and output to ConsoleLog,
145→// and returns the result. If the agent reports a transient API error, the
146→// prompt is retried once after a short delay. The caller should still check err.
147→func (s *RepoState) RunPrompt(t *testing.T, ctx context.Context, prompt string, opts ...agents.Option) (agents.Output, error) {
148→	t.Helper()
149→	out, err := s.Agent.RunPrompt(ctx, s.Dir, prompt, opts...)
150→	s.logPromptResult(out)
151→
152→	if err != nil && s.Agent.IsTransientError(out, err) {
153→		t.Logf("transient API error detected, retrying in 5s: %v", err)
154→		s.ConsoleLog.WriteString("> [retry] transient error, waiting 5s...\n")
155→		select {
156→		case <-time.After(5 * time.Second):
157→		case <-ctx.Done():
158→			return out, err
159→		}
160→		out, err = s.Agent.RunPrompt(ctx, s.Dir, prompt, opts...)
161→		s.logPromptResult(out)
162→	}
163→
164→	return out, err
165→}
