354→// WaitForSessionMetadata polls until session metadata exists on the checkpoint
355→// branch for the given checkpoint ID and session index, then returns it.
356→// This handles the race where the checkpoint branch advances before session
357→// metadata is fully committed.
358→func WaitForSessionMetadata(t *testing.T, dir string, checkpointID string, sessionIndex int, timeout time.Duration) SessionMetadata {
359→	t.Helper()
360→
361→	path := fmt.Sprintf("%s/%d/metadata.json", CheckpointPath(checkpointID), sessionIndex)
362→	blob := "entire/checkpoints/v1:" + path
363→
364→	deadline := time.Now().Add(timeout)
365→	for time.Now().Before(deadline) {
366→		raw := gitOutputSafe(dir, "show", blob)
367→		if raw != "" {
368→			var meta SessionMetadata
369→			if err := json.Unmarshal([]byte(raw), &meta); err != nil {
370→				t.Fatalf("unmarshal session metadata from %s: %v", blob, err)
371→			}
372→			return meta
373→		}
374→		time.Sleep(500 * time.Millisecond)
375→	}
376→	t.Fatalf("session metadata %s did not appear within %s", blob, timeout)
377→	return SessionMetadata{}
378→}
