 88→func (s *TmuxSession) WaitFor(pattern string, timeout time.Duration) (string, error) {
 89→	re, err := regexp.Compile(pattern)
 90→	if err != nil {
 91→		return "", fmt.Errorf("invalid pattern: %w", err)
 92→	}
 93→
 94→	deadline := time.Now().Add(timeout)
 95→	var matchedAt time.Time
 96→	var lastStable string
 97→	contentChanged := s.stableAtSend == "" // skip change requirement for initial waits
 98→
 99→	for time.Now().Before(deadline) {
100→		content := s.Capture()
101→		stable := stableContent(content)
102→
103→		if !re.MatchString(content) {
104→			// Pattern lost — reset
105→			matchedAt = time.Time{}
106→			lastStable = ""
107→			time.Sleep(pollInterval)
108→			continue
109→		}
110→
111→		// Detect content change since Send was called
112→		if !contentChanged && stable != s.stableAtSend {
113→			contentChanged = true
114→		}
115→
116→		if stable != lastStable {
117→			// Pattern matches but content is still changing — reset settle timer
118→			matchedAt = time.Now()
119→			lastStable = stable
120→			time.Sleep(pollInterval)
121→			continue
122→		}
123→
124→		// Pattern matches and content hasn't changed since matchedAt.
125→		// Only settle if content changed at least once after Send
126→		// (prevents false settle on echoed input before agent starts).
127→		if contentChanged && time.Since(matchedAt) >= settleTime {
128→			return content, nil
129→		}
130→
131→		time.Sleep(pollInterval)
132→	}
133→	content := s.Capture()
134→	return content, fmt.Errorf("timed out waiting for %q after %s\n--- pane content ---\n%s\n--- end pane content ---", pattern, timeout, content)
135→}
